import React, { useState, useEffect } from 'react';

// Effect on mount (empty deps)
function PageTitle({ title }: { title: string }) {
  useEffect(() => {
    document.title = title;
  }, [title]);  // re-run when title changes

  return <h1>{title}</h1>;
}

// Effect with cleanup (event listener)
function WindowSizeTracker() {
  const [width, setWidth] = useState(window.innerWidth);

  useEffect(() => {
    const handleResize = () => setWidth(window.innerWidth);

    window.addEventListener('resize', handleResize);
    return () => {
      window.removeEventListener('resize', handleResize);
    };
  }, []);  // empty array = subscribe once, cleanup on unmount

  return <p>Window width: {width}px</p>;
}

// Data fetching with AbortController
interface User {
  id: number;
  name: string;
}

function UserProfile({ userId }: { userId: number }) {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const abortController = new AbortController();

    async function fetchUser() {
      setLoading(true);
      setError(null);

      try {
        const response = await fetch(
          `https://api.example.com/users/${userId}`,
          { signal: abortController.signal }
        );
        if (!response.ok) throw new Error('Failed to fetch');
        const data = await response.json();
        if (!abortController.signal.aborted) {
          setUser(data);
        }
      } catch (err) {
        if (err instanceof Error && err.name !== 'AbortError') {
          setError(err.message);
        }
      } finally {
        if (!abortController.signal.aborted) {
          setLoading(false);
        }
      }
    }

    fetchUser();

    return () => {
      abortController.abort();  // cancel request on unmount or userId change
    };
  }, [userId]);  // re-fetch when userId changes

  if (loading) return <p>Loading...</p>;
  if (error) return <p>Error: {error}</p>;
  return <p>{user?.name}</p>;
}

// Timing with cleanup
function Timer() {
  const [seconds, setSeconds] = useState(0);

  useEffect(() => {
    const interval = setInterval(() => {
      setSeconds(prev => prev + 1);
    }, 1000);

    return () => clearInterval(interval);  // cleanup on unmount
  }, []);

  return <p>Timer: {seconds}s</p>;
}

