// Props interface
interface AvatarProps {
  src: string;
  alt: string;
  size?: 'sm' | 'md' | 'lg';
}

function Avatar({ src, alt, size = 'md' }: AvatarProps) {
  const sizeMap = { sm: 32, md: 48, lg: 64 };

  return (
    <img
      src={src}
      alt={alt}
      width={sizeMap[size]}
      height={sizeMap[size]}
      className={`rounded-full`}
    />
  );
}

