  return (
    <div>
      {message && <div className="alert">{message}</div>}
      {/* Better: convert to boolean to avoid rendering 0/falsy */}
      {!!message && <div className="alert">{message}</div>}
    </div>
  );
}

// Multiple conditions with early return
function Dashboard({ user }: { user: User | null }) {
  // Guard: not authenticated
  if (!user) {
    return <LoginPrompt />;
  }

  // Guard: no permission
  if (!user.hasAccess) {
    return <AccessDenied />;
  }

  // Normal render
  return (
    <div>
      <h1>Dashboard</h1>
      <UserPanel user={user} />
    </div>
  );
}

