// Enum pattern with switch inside
function OrderState({ step }: { step: 1 | 2 | 3 | 4 }) {
  const getStepContent = () => {
    switch (step) {
      case 1: return 'Cart';
      case 2: return 'Shipping';
      case 3: return 'Payment';
      case 4: return 'Confirmation';
      default: return null;
    }
  };

  return <p>Current: {getStepContent()}</p>;
}
